def beautifulPartitions(s, k, minLength):
    MOD = 10 ** 9 + 7
    n = len(s)
    prime = set('2357')
    if s[0] not in prime or s[-1] in prime:
        return 0

    def ok(i):
        if i == 0:
            return s[0] in prime
        if i == n:
            return s[n - 1] not in prime
        return s[i - 1] not in prime and s[i] in prime

    dp = [0] * (n + 1)
    dp[0] = 1
    for j in range(1, k + 1):
        ndp = [0] * (n + 1)
        pref = [0] * (n + 2)
        for b in range(n + 1):
            pref[b + 1] = (pref[b] + dp[b]) % MOD
        for b in range(1, n + 1):
            if not ok(b):
                continue
            hi = b - minLength
            if hi < 0:
                continue
            ndp[b] = pref[hi + 1] % MOD
        dp = ndp
    return dp[n] % MOD
